/**
 * Issues a fresh signing secret, returned only in this response. During the optional grace period, deliveries carry `v1=` signature entries for both the new and the old secret so receivers can switch without dropping deliveries; afterwards only the new secret is used.
 * @summary Rotate a webhook endpoint's signing secret
 */
export const RotateWebhookSecretParams = zod.object({
  "id": zod.uuid()
})

export const rotateWebhookSecretBodyGracePeriodHoursMin = 0;



export const RotateWebhookSecretBody = zod.object({
  "gracePeriodHours": zod.int().min(rotateWebhookSecretBodyGracePeriodHoursMin).optional().describe('Hours the old secret keeps being honored alongside the new one (deliveries carry both signatures). 0 revokes it immediately. Defaults to 24; capped at 168 (7 days).')
})

export const RotateWebhookSecretResponse = zod.object({
  "id": zod.uuid(),
  "url": zod.string(),
  "events": zod.array(zod.string()),
  "isActive": zod.boolean(),
  "createdAt": zod.string().optional(),
  "previousSecretExpiresAt": zod.string().nullish().describe('When a secret rotation grace window is active, the ISO timestamp after which the old secret stops being honored. Null when no rotation is in flight. The old secret itself is never returned.')
}).and(zod.object({
  "secret": zod.string().describe('HMAC-SHA256 signing secret. Shown only once at creation and stored encrypted. Deliveries carry an `X-Painless-Signature` header of the form `t=<unix_seconds>,v1=<hex hmac>` where the HMAC-SHA256 is computed over `\"<t>.<raw request body>\"` using this secret. Receivers should recompute the HMAC, compare in constant time, and reject timestamps older than ~5 minutes.')
}))


